+    public void paint(Graphics2D g, float xstep, double minY, 
+                      double maxY, double rangeY, double height) {
+      g.setColor(color);
+      g.setStroke(new BasicStroke(1.0f));
+
+      for (int i = 0; i < buffer.size() - 1; ++i) {
+        g.drawLine(
